"""A small PTY-backed interactive Bash terminal."""

from __future__ import annotations

import errno
import fcntl
import os
import pty
import select
import signal
import struct
import subprocess
import termios
import time
from typing import Optional

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """Run an interactive Bash shell attached to a pseudo-terminal.

    Keystrokes are written verbatim to the shell's PTY, so control characters
    (for example ``\x03``) and interactive terminal applications work as they
    do in a regular terminal. Output read from the PTY is kept in ``output``;
    ``read_output`` returns and clears the unread portion.
    """

    def __init__(self, *, cwd: Optional[str] = None, env: Optional[dict] = None,
                 rows: int = 24, cols: int = 80, encoding: str = "utf-8") -> None:
        self.encoding = encoding
        self._output = ""
        self._unread = ""
        self._closed = False
        master_fd, slave_fd = pty.openpty()
        fcntl.ioctl(slave_fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        child_env = os.environ.copy()
        child_env.setdefault("TERM", "xterm-256color")
        if env:
            child_env.update(env)
        try:
            self.process = subprocess.Popen(
                ["bash", "--noprofile", "-i"],
                stdin=slave_fd, stdout=slave_fd, stderr=slave_fd,
                cwd=cwd, env=child_env, close_fds=True,
                preexec_fn=self._make_controlling_tty(slave_fd),
            )
        finally:
            os.close(slave_fd)
        self._fd = master_fd
        os.set_blocking(self._fd, False)
        # Drain startup output without delaying construction for a fixed period.
        self._collect(0.15)

    @staticmethod
    def _make_controlling_tty(slave_fd: int):
        def setup() -> None:
            os.setsid()
            fcntl.ioctl(slave_fd, termios.TIOCSCTTY, 0)
        return setup

    @property
    def output(self) -> str:
        """All terminal output collected so far (including echoed input)."""
        self._collect(0)
        return self._output

    def read_output(self) -> str:
        """Return output not previously read through this method."""
        self._collect(0)
        result, self._unread = self._unread, ""
        return result

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        if self._closed:
            raise RuntimeError("terminal is closed")
        data = keystrokes.encode(self.encoding)
        view = memoryview(data)
        while view:
            try:
                written = os.write(self._fd, view)
                view = view[written:]
            except BlockingIOError:
                self._collect(0.05)
        if wait_sec > 0:
            self._collect(wait_sec)
        else:
            self._collect(0.03)

    def _collect(self, timeout: float) -> None:
        if self._closed:
            return
        deadline = time.monotonic() + max(0.0, timeout)
        first = True
        while True:
            remaining = max(0.0, deadline - time.monotonic()) if timeout > 0 else 0
            try:
                ready, _, _ = select.select([self._fd], [], [], remaining if first else 0)
            except (OSError, ValueError):
                return
            first = False
            if not ready:
                return
            try:
                chunk = os.read(self._fd, 65536)
            except BlockingIOError:
                continue
            except OSError as exc:
                if exc.errno == errno.EIO:  # PTY slave closed after shell exit
                    return
                raise
            if not chunk:
                return
            decoded = chunk.decode(self.encoding, errors="replace")
            self._output += decoded
            self._unread += decoded

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            os.close(self._fd)
        except OSError:
            pass
        if self.process.poll() is None:
            try:
                os.killpg(self.process.pid, signal.SIGHUP)
            except ProcessLookupError:
                pass
            try:
                self.process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                self.process.kill()
                self.process.wait()

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, *_exc) -> None:
        self.close()

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass

